/**
 * Facts the site chatbot answers from, derived from catalogue.json and app/content/services.ts.
 * `npm run prompt:data` writes the result to workers/techpravaha-api/src/prompt-data.json (checked in,
 * and regenerated by deploy-worker.yml before every Worker deploy); tests/prompt-data.test.ts checks
 * the generator and the checked-in file's structure.
 *
 * Every number the bot may quote is computed here (GST totals, amounts due at checkout), so the
 * model never does arithmetic on prices.
 */
import { catalogue, chargedNow, withGst, type Tier } from '../../app/lib/catalogue';
import { SERVICES } from '../../app/content/services';

/**
 * Mirrors the home page meta description and the tagline in app/lib/site.ts. Kept as a constant
 * because site.ts reads import.meta.env, which does not exist under tsx.
 */
export const POSITIONING =
  'Tech Pravaha is a design and build studio for things you launch: websites, apps, AI assistants, WhatsApp automation, content automation and UI/UX design. Delivered in weeks at a price you can see. Yogesh Laddha, the founder, designs and builds every project.';
export const TAGLINE = 'Beautiful things, shipped.';

/** The three FAQ answers per service the bot needs most: tax, when the clock starts, how payment works. */
const FAQ_PREFIXES = ['Is GST included', 'When does the timeline start', 'How does payment work'] as const;

export interface PromptTier {
  id: string;
  label: string;
  tagline: string;
  buyable: boolean;
  /** Fixed price before GST, or null for quote-only tiers. */
  price: number | null;
  /** Starting price before GST for quote-only tiers. */
  from?: number;
  /** price + GST, whole rupees. */
  totalWithGst?: number;
  /** Share of the GST-inclusive total charged at checkout, 1 to 100. */
  depositPct?: number;
  /** Amount charged at checkout, GST included, whole rupees. */
  dueAtCheckout?: number;
  weeks?: number;
  days?: number;
  payment?: string;
  terms?: string;
  includes: string[];
  /** Site path that starts checkout for a buyable tier. */
  checkout?: string;
}

export interface PromptService {
  id: string;
  name: string;
  short: string;
  route: string;
  h1: string;
  subline: string;
  faq: { q: string; a: string }[];
  afterPay: { title: string; body: string }[];
  tiers: PromptTier[];
}

export interface PromptData {
  positioning: string;
  tagline: string;
  currency: 'INR';
  gstPct: number;
  services: PromptService[];
  addons: { name: string; from: number; per: string; blurb: string }[];
  contact: {
    email: string;
    whatsapp: string;
    contactPath: string;
    pricingPath: string;
    servicesPath: string;
    refundsPath: string;
  };
}

function promptTier(t: Tier): PromptTier {
  const out: Omit<PromptTier, 'includes'> = { id: t.id, label: t.label, tagline: t.tagline, buyable: t.buyable, price: t.price };
  if (t.from !== undefined) out.from = t.from;
  if (t.buyable && t.price !== null) {
    out.totalWithGst = withGst(t.price);
    out.depositPct = t.depositPct ?? 100;
    out.dueAtCheckout = chargedNow({ price: t.price, depositPct: t.depositPct });
    out.checkout = `/checkout/${t.id}`;
  }
  if (t.weeks !== undefined) out.weeks = t.weeks;
  if (t.days !== undefined) out.days = t.days;
  if (t.payment !== undefined) out.payment = t.payment;
  if (t.terms !== undefined) out.terms = t.terms;
  return { ...out, includes: [...t.includes] };
}

export function buildPromptData(): PromptData {
  const services = [...catalogue.services]
    .sort((a, b) => a.order - b.order)
    .map((s): PromptService => {
      const content = SERVICES[s.id];
      if (!content) throw new Error(`prompt-data: no content for service ${s.id}`);
      const faq = FAQ_PREFIXES.map((prefix) => {
        const hit = content.faq.find((f) => f.q.startsWith(prefix));
        if (!hit) throw new Error(`prompt-data: service ${s.id} has no FAQ starting "${prefix}"`);
        return { q: hit.q, a: hit.a };
      });
      return {
        id: s.id,
        name: s.name,
        short: s.short,
        route: s.route,
        h1: content.h1,
        subline: content.subline,
        faq,
        afterPay: content.afterPay.map(({ title, body }) => ({ title, body })),
        tiers: s.tiers.map(promptTier),
      };
    });

  return {
    positioning: POSITIONING,
    tagline: TAGLINE,
    currency: 'INR',
    gstPct: Math.round(catalogue.gst * 100),
    services,
    addons: catalogue.addons.map(({ name, from, per, blurb }) => ({ name, from, per, blurb })),
    contact: {
      email: 'hello@techpravaha.com',
      whatsapp: 'WhatsApp is available from the WhatsApp button on every page of the site.',
      contactPath: '/contact',
      pricingPath: '/pricing',
      servicesPath: '/services',
      refundsPath: '/refunds',
    },
  };
}

/** Exact file contents written by `npm run prompt:data`. */
export function promptDataJson(): string {
  return `${JSON.stringify(buildPromptData(), null, 2)}\n`;
}
